package com.utegear.service;
import com.utegear.dto.catalog.CategorySummary; import com.utegear.entity.Category; import com.utegear.exception.ApiException; import com.utegear.repository.CategoryRepository; import com.utegear.util.Slugifier; import java.util.List; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class CategoryService { private final CategoryRepository repository; public CategoryService(CategoryRepository repository){this.repository=repository;} @Transactional public CategorySummary create(String name,String description,int sortOrder){String slug=Slugifier.slugify(name); if(repository.existsByNameIgnoreCase(name.trim())||repository.existsBySlug(slug)) throw new ApiException(HttpStatus.CONFLICT,"CATEGORY_ALREADY_EXISTS","Danh mục đã tồn tại"); return CategorySummary.from(repository.save(new Category(name.trim(),slug,description,sortOrder)));} @Transactional(readOnly=true) public List<CategorySummary> active(){return repository.findByActiveTrueOrderBySortOrderAscNameAsc().stream().map(CategorySummary::from).toList();} }
